"""
Django settings for config project.
Django 6.1 - TOUKPEDIO
Hébergement : Vercel
Base de données : Neon PostgreSQL
"""

import os
from pathlib import Path
from urllib.parse import parse_qsl, unquote, urlsplit

from dotenv import load_dotenv
from django.core.exceptions import ImproperlyConfigured


# ============================================================
# CHEMINS ET ENVIRONNEMENT
# ============================================================

BASE_DIR = Path(__file__).resolve().parent.parent

load_dotenv(BASE_DIR / ".env.local")
load_dotenv(BASE_DIR / ".env")

IS_VERCEL = os.getenv("VERCEL") == "1"


# ============================================================
# SÉCURITÉ
# ============================================================

SECRET_KEY = os.getenv("DJANGO_SECRET_KEY", "").strip()

if not SECRET_KEY:
    raise ImproperlyConfigured(
        "DJANGO_SECRET_KEY doit être configurée dans l'environnement."
    )

DEBUG = os.getenv(
    "DJANGO_DEBUG", "false"
).strip().lower() == "true"

ALLOWED_HOSTS = [
    host.strip()
    for host in os.getenv(
        "DJANGO_ALLOWED_HOSTS",
        "localhost,127.0.0.1",
    ).split(",")
    if host.strip()
]

if IS_VERCEL:
    ALLOWED_HOSTS.extend([".vercel.app", ".now.sh"])

    vercel_url = os.getenv("VERCEL_URL", "").strip()

    if vercel_url and vercel_url not in ALLOWED_HOSTS:
        ALLOWED_HOSTS.append(vercel_url)

CSRF_TRUSTED_ORIGINS = [
    origin.strip()
    for origin in os.getenv(
        "DJANGO_CSRF_TRUSTED_ORIGINS", ""
    ).split(",")
    if origin.strip()
]

if IS_VERCEL:
    CSRF_TRUSTED_ORIGINS.append("https://*.vercel.app")


# ============================================================
# APPLICATIONS
# ============================================================

INSTALLED_APPS = [
    "django.contrib.admin",
    "django.contrib.auth",
    "django.contrib.contenttypes",
    "django.contrib.sessions",
    "django.contrib.messages",
    "django.contrib.staticfiles",
    "sante",
    "Api",
]

if not IS_VERCEL:
    INSTALLED_APPS.insert(0, "daphne")


# ============================================================
# MIDDLEWARE
# ============================================================

MIDDLEWARE = [
    "django.middleware.security.SecurityMiddleware",
    "django.contrib.sessions.middleware.SessionMiddleware",
    "django.middleware.common.CommonMiddleware",
    "django.middleware.csrf.CsrfViewMiddleware",
    "django.contrib.auth.middleware.AuthenticationMiddleware",
    "django.contrib.messages.middleware.MessageMiddleware",
    "django.middleware.clickjacking.XFrameOptionsMiddleware",
]


# ============================================================
# URLS ET TEMPLATES
# ============================================================

ROOT_URLCONF = "config.urls"

TEMPLATES = [
    {
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "DIRS": [],
        "APP_DIRS": True,
        "OPTIONS": {
            "context_processors": [
                "django.template.context_processors.request",
                "django.contrib.auth.context_processors.auth",
                "django.contrib.messages.context_processors.messages",
            ],
        },
    },
]

WSGI_APPLICATION = "config.wsgi.application"
ASGI_APPLICATION = "config.asgi.application"


# ============================================================
# CHANNELS / WEBSOCKET
# ============================================================

REDIS_URL = os.getenv("REDIS_URL", "").strip()

if not REDIS_URL and not DEBUG and not IS_VERCEL:
    raise ImproperlyConfigured(
        "REDIS_URL doit être configurée pour la messagerie "
        "WebSocket en production hors Vercel."
    )

if REDIS_URL:
    CHANNEL_LAYERS = {
        "default": {
            "BACKEND": "channels_redis.core.RedisChannelLayer",
            "CONFIG": {
                "hosts": [REDIS_URL],
            },
        }
    }
else:
    CHANNEL_LAYERS = {
        "default": {
            "BACKEND": "channels.layers.InMemoryChannelLayer",
        }
    }


# ============================================================
# BASE DE DONNÉES : NEON POSTGRESQL
# ============================================================

DATABASE_URL = os.getenv("DATABASE_URL", "").strip()

if DATABASE_URL:
    database_url = urlsplit(DATABASE_URL)

    if database_url.scheme not in {"postgres", "postgresql"}:
        raise ImproperlyConfigured(
            "DATABASE_URL doit utiliser postgres:// "
            "ou postgresql://."
        )

    database_options = dict(parse_qsl(database_url.query))

    if not DEBUG:
        database_options.setdefault("sslmode", "require")

    DATABASES = {
        "default": {
            "ENGINE": "django.db.backends.postgresql",
            "NAME": unquote(database_url.path.lstrip("/")),
            "USER": unquote(database_url.username or ""),
            "PASSWORD": unquote(database_url.password or ""),
            "HOST": database_url.hostname or "",
            "PORT": str(database_url.port or ""),
            "CONN_MAX_AGE": 0,
            "OPTIONS": database_options,
        }
    }

elif IS_VERCEL:
    raise ImproperlyConfigured(
        "DATABASE_URL doit être configurée sur Vercel."
    )

else:
    DATABASES = {
        "default": {
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": BASE_DIR / "db.sqlite3",
        }
    }


